const UPGRADE_SECTIONS=[['powers','権能','深淵・黒翼・堕天・断罪など','権能の入手・強化・装備','violet'],['marks','刻印','刻印の装備・強化・管理','既存の刻印機能','red'],['resonance','権能共鳴','権能を組み合わせた共鳴権能','共鳴権能の作成・強化','gold'],['training','才能＆技','ステータス・才能・技の育成','既存の才能・技の育成','blue'],['summon','黒翼召喚','黒翼の召喚・育成・管理','既存の召喚機能','violet']];
function upgradeHero(a,detail=false){return `<header class="upgrade-hero"><img class="upgrade-hero-art" src="${UPGRADE_HERO}" alt=""><div class="upgrade-hero-copy"><span class="upgrade-crest" aria-hidden="true">✧</span><div><h1>${detail?'権能強化':'強化'}</h1><small>POWER UP</small><p>${detail?'強化する権能を選択してください':'強化したい項目を選択してください'}</p></div></div><div class="upgrade-wallet">権能ポイント <strong>✦ ${n(a.p)} P</strong></div></header>`;}
function upgrade(a){const section=UPGRADE_SECTIONS.find(x=>x[0]===tab);return `<div class="upgrade-ui">${upgradeHero(a,tab==='powers')}${tab==='overview'?`<section class="upgrade-category-list" aria-label="強化カテゴリ">${UPGRADE_SECTIONS.map(([id,title,desc,more,tone])=>`<button class="upgrade-category tone-${tone}" data-action="tab" data-id="${id}"><img src="${UPGRADE_ICONS[id]}" alt="" class="upgrade-category-icon"><span class="upgrade-category-copy"><strong>${title}</strong><span>${desc}</span><small>${more}</small></span><span class="upgrade-category-chevron" aria-hidden="true">›</span></button>`).join('')}</section><div class="upgrade-info">${uiIcon('book',26)}<span><strong>強化について</strong><small>項目を選択すると、既存の育成メニューに進みます。</small></span></div>`:`<section class="upgrade-subpage" aria-label="${section?.[1]||'育成'}">${tab==='powers'?powersView(a):`<h2 class="upgrade-subtitle">${section?.[1]||'育成'}</h2>${tab==='marks'?marksView(a):tab==='resonance'?resonanceView(a):tab==='training'?trainingView(a):summonView(a)}`}</section>`}</div>`;}
function powerStatus(a,p){
 const info=powerUpgradeInfo(a,p.id),selected=a.equipped.includes(p.id);
 const state=!info.lv?(p.id==='star'?'locked':'unowned'):info.max?'max':info.canUpgrade?'ready':'insufficient';
 const label={locked:'未解放',unowned:'未所持',max:'★ 最大レベル',ready:'↑ 強化可能',insufficient:'◇ 素材不足'}[state];
 return {...info,selected,state,label};
}
function powerDetails(a,p){
 const v=powerStatus(a,p),growth=lv=>Math.round((powerGrowth(lv)-1)*100),isStar=p.id==='star';
 const effect=lv=>`<p>${esc(p.effect)}</p>${!isStar?`<div class="detail-growth">育成補正：基礎HP・攻撃・防御・速度 <strong>＋${growth(lv)}%</strong></div>`:''}`;
 const next=v.max?'<p>★ 最大レベルに到達しています。</p>':!v.lv?`<p>${esc(a.route20===1&&p.id==='judge'?'第15階層撃破 / 120P':p.source)}</p><small>${isStar?`実績 ${a.achieved.length} / ${ACHIEVEMENTS.length}`:'入手するとLv.1の固有効果が有効になります。'}</small><h3 class="unlock-effect-title">${isStar?'解放時の効果 · Lv.5':'入手時の効果 · Lv.1'}</h3>${effect(isStar?5:1)}`:effect(v.lv+1);
 return `<div class="upgrade-detail-modal"><header class="power-detail-heading"><img ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div><strong>${p.name}</strong><span>${v.lv?'Lv.'+v.lv+' / 5':'未解放・未所持'}</span><span class="power-state-badge badge-${v.state}">${v.label}</span>${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}</div></header><section class="upgrade-detail-section"><h3>現在の効果${v.lv?' · Lv.'+v.lv:''}</h3>${v.lv?effect(v.lv):'<p>未所持のため、まだ効果は発動しません。</p>'}</section><section class="upgrade-detail-section next-effect"><h3>${v.max?'強化完了':v.lv?'次レベルの効果 · Lv.'+(v.lv+1):'解放・入手条件'}</h3>${next}</section><dl class="power-detail-materials"><div><dt>強化に必要な欠片</dt><dd>${v.max?'— 最大レベル':!v.lv?'— 入手後に強化':n(v.cost)+' 個'}</dd></div><div><dt>所持欠片</dt><dd>${isStar?'— 実績報酬':n(v.have)+' 個'}</dd></div>${v.lv&&!v.max?`<div class="material-balance"><dt>${v.canUpgrade?'強化できます':'不足している欠片'}</dt><dd>${v.canUpgrade?'↑ 強化可能':n(v.cost-v.have)+' 個'}</dd></div>`:''}</dl><p class="small">装備枠は2つ。入手・装備・強化は一覧から操作できます。${!isStar?'固有効果はLv.1から有効で、Lv.2〜5は基礎能力の育成補正が上昇します。':''}</p></div>`;
}
function powersView(a){
 const ordered=['abyss','wing','fallen','king','judge','star'].map(id=>POWERS.find(p=>p.id===id));
 if(powerSort==='owned')ordered.sort((x,y)=>Number(!!a.powers[y.id])-Number(!!a.powers[x.id]));
 return `<div class="upgrade-powers-header"><h2>権能一覧</h2><button class="ghost" data-action="sortPowers" aria-label="権能一覧を並び替える">${powerSort==='owned'?'通常の順序':'所持優先に並び替え'}</button></div><div class="upgrade-power-grid">${ordered.map(p=>{
 const v=powerStatus(a,p),costText=!v.lv?(p.id==='star'?`実績 ${a.achieved.length}/${ACHIEVEMENTS.length}`:'入手 120 P'):v.max?'育成完了':`欠片 ${n(v.have)} / ${n(v.cost)}`;
 const action=v.lv?`${button(v.selected?'装備解除':'装備する','equipPower',p.id,'ghost equip-action')}${button(v.max?'MAX':'強化','upgradePower',p.id,'upgrade-action',!v.canUpgrade)}`:button(p.id==='star'?'解放条件':'120Pで入手',p.id==='star'?'powerDetails':'buyPower',p.id,'upgrade-action',p.id!=='star'&&a.p<120);
 return `<article class="upgrade-power-card state-${v.state} ${v.selected?'equipped':''}"><div class="upgrade-power-main"><img class="upgrade-power-art" ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div class="upgrade-power-identity"><h3>${p.name}</h3><p class="upgrade-power-level">${v.lv?'Lv.'+v.lv+' / 5':'未所持'}</p></div><button class="upgrade-power-detail" data-action="powerDetails" data-id="${p.id}" aria-label="${p.name}の詳細を見る">${uiIcon('search',19)}</button></div><div class="power-card-badges">${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}<span class="power-state-badge badge-${v.state}">${v.label}</span></div><div class="upgrade-power-meter" aria-label="強化レベル ${v.lv}/5"><span style="width:${v.lv*20}%"></span></div><div class="upgrade-power-cost">${costText}</div><div class="upgrade-power-actions">${action}</div></article>`;
 }).join('')}</div><div class="upgrade-info">${uiIcon('book',26)}<span><strong>権能の詳細</strong><small>虫眼鏡で現在・次レベルの効果と必要素材を比較できます。</small></span></div>`;
}
function marksView(a){return `<div class="notice">刻印は独立した3枠。所持 ${a.marks.length}/10・装備 ${a.markEquip.length}/3。権能連動型は対応する通常権能の装備が必要です。<br>旧刻印の所持・装備は引き継がれます。戦闘中の装備変更は次の戦闘から反映されます。</div><div class="grid">${MARKS.map(m=>`<section class="card power-card ${a.markEquip.includes(m.id)?'selected':''}" data-mark="${m.id}"><div class="row"><div class="emblem">${m.icon}</div><div><h3>${m.name}</h3><small>${a.markEquip.includes(m.id)?'装備中':a.marks.includes(m.id)?'所持':'未所持'}${m.power?' / '+(a.equipped.includes(m.power)?'対応権能を装備中':'対応権能が未装備'):''}</small></div></div><p>${m.effect}</p><div class="actions">${a.marks.includes(m.id)?button(a.markEquip.includes(m.id)?'装備解除':'装備する','equipMark',m.id,'primary'):button(`${m.cost}P で入手`,'buyMark',m.id,'',a.p<m.cost)}</div></section>`).join('')}</div>`;}
function resonanceView(a){return `<div class="notice">${midgameUnlocked(a)?'共鳴解放済み':'通常カイザー第10階層の撃破記録で解放'}。Lv.5権能2つを消費する永久1回の合成です。余剰欠片は共鳴片へ1:1変換。消費後も権能を120Pで再入手できます。</div><div class="grid">${RECIPES.map(r=>{const lv=a.resonance[r.id],done=a.recipes.includes(r.id),eligible=r.live&&midgameUnlocked(a)&&r.parts.every(x=>a.powers[x]===5)&&!done;return `<section class="card power-card ${a.equipped.includes(r.id)?'selected':''}"><div class="row between"><h3>◇ ${r.name}</h3><span class="tag">${lv?'Lv. '+lv:r.live?'LIVE RECIPE':'開発者専用'}</span></div><div class="small">${r.parts.map(x=>name(x)+' Lv.'+(a.powers[x]||0)).join(' ＋ ')}</div><p>${r.effect}</p><div class="effect">補完倍率：Lv.1 基礎全能力1.20倍 → Lv.5 1.68倍。現在 ${lv?(1.2+(lv-1)*.12).toFixed(2):'—'}倍。${lv&&lv<5?'次 '+(1.2+lv*.12).toFixed(2)+'倍':''}<br>強化：40 / 80 / 120 / 160共鳴片</div><div class="actions">${lv?`${button(a.equipped.includes(r.id)?'装備解除':'装備する','equipPower',r.id,'primary')}${button(lv>=5?'MAX':`強化 ${BALANCE.resCosts[lv-1]}片`,'upgradePower',r.id,'',lv>=5||a.resShards<BALANCE.resCosts[lv-1])}`:button(done?'合成済み':r.live?'共鳴する':'通常合成不可','askFuse',r.id,'',!eligible)}</div></section>`;}).join('')}</div>`;}
function trainingView(a){return `<div class="grid"><section class="card stack"><h3>いれーな育成</h3>${[['level','基礎レベル',a.level,150,40+a.level*3,'HP＋42 / 攻撃＋13 / 防御＋5 / 速度＋2'],['talent','才能',a.talent,20,a.talent*30,`攻撃補正 ${Math.round((a.talent-1)*3.5)}% → ${Math.round(a.talent*3.5)}%`],['feather','黒翼・羽弾',a.skills.feather,10,a.skills.feather*35,`技倍率 ${(1.95*(1+(a.skills.feather-1)*.07)).toFixed(2)} → ${(1.95*(1+a.skills.feather*.07)).toFixed(2)}`],['destruction','破壊の権能',a.skills.destruction,10,a.skills.destruction*35,`技倍率 ${(2.4*(1+(a.skills.destruction-1)*.1)).toFixed(2)} → ${(2.4*(1+a.skills.destruction*.1)).toFixed(2)}`],['ultimate','超堕天撃',a.skills.ultimate,10,a.skills.ultimate*35,`技倍率 ${(5.4*(1+(a.skills.ultimate-1)*.08)).toFixed(2)} → ${(5.4*(1+a.skills.ultimate*.08)).toFixed(2)}`]].map(([id,title,lv,max,cost,text])=>`<div><div class="row between"><div>${title}<small> Lv.${lv}/${max}</small><div class="small">${lv<max?text:'最大強化済み'}</div></div>${button(lv>=max?'MAX':`${cost}Pで強化`,'train',id,'',lv>=max||a.p<cost)}</div></div>`).join('')}</section><div class="stack"><section class="card"><h3>通常ステータス調整</h3><p class="small">残り ${a.sp}P / 通常Lv.100初撃破で50P、一度だけ獲得。</p>${allocations(a,false)}</section><section class="card"><h3>最終決戦専用・独立150P</h3><p class="small">残り ${a.finalBuild.points}P / 通常いれーなに影響しません。</p>${allocations(a,true)}${button('専用配分をリセット','resetFinal','','ghost small')}</section></div></div>`;}
function allocations(a,final){return `<div class="statgrid">${[['hp','HP',final?80:35],['atk','攻撃',final?35:12],['def','防御',final?22:9],['spd','速度',final?6:3]].map(([id,label,value])=>`<div><span class="small">${label} ＋${value} / ${final?a.finalBuild[id]:a.stats[id]}P</span><div>${button('＋1P',final?'allocateFinal':'allocate',id,'ghost',final?a.finalBuild.points<=0:a.sp<=0)}</div></div>`).join('')}</div>`;}
// Display tiers classify existing rewards; the original missing-first lottery is unchanged.
const SUMMON_RARITY={'黒翼の欠片':'R','深淵結晶':'R','堕天の羽根':'R','断罪の印章':'SR','王権の残光':'SR','星のかけら':'SSR'};
function summonRates(a){
 const missing=SUMMONS.filter(x=>!a.collection.includes(x)),pool=missing.length?missing:SUMMONS;
 return `<details class="summon-rates"><summary>レアリティ・現在の排出率</summary><p class="small">次の1回の確率です。10連も1枚ごとに未所持優先で再計算します。レアリティは報酬の区分で、欠片の数量や性能は変わりません。</p>${['R','SR','SSR'].map(t=>`<p><b class="rarity-${t}">${t}</b> ${(100*pool.filter(x=>SUMMON_RARITY[x]===t).length/pool.length).toFixed(2)}%</p>`).join('')}<ul>${SUMMONS.map(x=>`<li>${SUMMON_RARITY[x]} · ${x}：${pool.includes(x)?(100/pool.length).toFixed(2):'0.00'}%</li>`).join('')}</ul></details>`;
}
function summonCinema(){
 const tier=summonSession.results.reduce((best,x)=>['R','SR','SSR'].indexOf(SUMMON_RARITY[x.reward])>['R','SR','SSR'].indexOf(best)?SUMMON_RARITY[x.reward]:best,'R');
 cinema('summon',tier,{R:'黒翼に宿る記憶',SR:'深淵が呼び覚ます輝き',SSR:'天星の扉が開く'}[tier],summonPresentation,{R:1400,SR:1900,SSR:2400}[tier]);
 const el=$('#cinema');el.classList.add('summon-cinema','rarity-'+tier);
 el.querySelectorAll('.tunnel').forEach(x=>x.remove());
 const field=document.createElement('div');field.className='summon-field';field.setAttribute('aria-hidden','true');field.innerHTML=`<img class="summon-crest" src="${SCENES.fallenCrest}" alt=""><div class="summon-ring"></div><div class="summon-ring outer"></div>${Array.from({length:tier==='SSR'?12:tier==='SR'?8:4},(_,i)=>`<i class="summon-ray" style="--angle:${i*30}deg;--delay:${i*.035}s"></i>`).join('')}`;
 el.prepend(field);
}
// Rewards are committed and saved once before the presentation starts.
function summonPresentation(){
 const {results,revealed}=summonSession,done=revealed===results.length;
 modal('黒翼召喚 — 星の記憶',`<div class="summon-opening" aria-hidden="true">${uiIcon('star',48)}</div><p class="summon-progress" role="status">${done?'召喚完了':`${revealed} / ${results.length} 枚を開封`}</p><div class="summon-results">${results.map((x,i)=>i<revealed?`<article class="summon-result rarity-${SUMMON_RARITY[x.reward]} ${x.dupe?'duplicate':'discovery'}"><span class="summon-seal" aria-hidden="true">${uiIcon('gem',32)}</span><span class="summon-label">${SUMMON_RARITY[x.reward]} · ${x.dupe?'獲得済み':'NEW'}</span><strong>${esc(x.reward)}</strong><small>権能欠片 ＋8${x.dupe?'<br>共鳴片 ＋5':''}</small></article>`:`<div class="summon-result sealed" aria-label="未開封 ${i+1}枚目"><span aria-hidden="true">✦</span></div>`).join('')}</div><p class="small">報酬は獲得済みです。閉じても失われません。</p>`,done?'':button('次の1枚を開く','summonReveal','','primary'));
 const head=document.createElement('header');head.className='summon-dialog-head';const title=$('#modal-title');title.before(head);head.append(title);if(!done)head.insertAdjacentHTML('beforeend',button('スキップ','summonAll','','ghost summon-skip-result'));
 $('#modal').classList.add('summon-dialog');$('#modal').scrollTop=0;$('#modal').querySelector('button')?.focus({preventScroll:true});
}
function summonView(a){return `<div class="grid"><section class="card stack"><div class="tag">BLACK WING SUMMON</div><h2>黒翼に、星の記憶を。</h2><div class="summon-sanctuary"><img src="${HOME_CARD_ART.summon}" alt="黒翼召喚の祭壇"><span>失われた記憶を、翼に。</span></div><p class="small">未所持を優先：未所持N種類から各1/Nの等確率。全6種収集後は各1/6。各報酬で権能欠片8個、重複時は共鳴片＋5。（排出仕様は補完）</p><div class="row">${button('単発 25P','summon','1','primary',a.p<25)}${button('10連 250P','summon','10','primary',a.p<250)}</div>${summonRates(a)}<div class="summon-wallet"><span>所持 <strong>${n(a.p)} P</strong></span><span>図鑑 <strong>${a.collection.length} / 6</strong></span></div><progress class="summon-collection-progress" max="6" value="${a.collection.length}" aria-label="召喚図鑑の収集状況"></progress><p class="small">通算 ${a.summons}回 · ${a.collection.length===6?'全種類収集済み。重複で共鳴片を獲得':'未収集の記憶を優先して獲得'}</p></section><section class="card"><h3>召喚図鑑</h3><div class="stack" style="margin-top:16px">${SUMMONS.map((x,i)=>`<div class="equip"><div class="emblem">${['✧','◈','⚖','♜','♛','✺'][i]}</div><div><strong>${a.collection.includes(x)?x:'？？？'}</strong><small>${SUMMON_RARITY[x]} · ${a.collection.includes(x)?'COLLECTED':'未収集'}</small></div></div>`).join('')}</div></section></div><div class="section-head"><h2>召喚履歴</h2><small>最新60件</small></div><section class="card"><div class="collection">${a.summonHistory.length?a.summonHistory.map(x=>`<span>${x.reward}${x.dupe?' / 共鳴片＋5':' / NEW'}</span>`).join(''):'まだ星の記憶はありません。'}</div></section>`;}
function enemyArt(b){if((b.main20||b.campaign)&&['normal','ex'].includes(b.mode))return `<img class="sprite portrait enemy-portrait" src="${CAMPAIGN_ART[b.mode]}" alt="${b.mode==='ex'?'EXカイザー':'カイザー'}の提供透過立ち絵">`;const src=enemyImage(b);if(src)return `<img class="sprite portrait enemy-portrait" src="${src}" alt="${esc(enemyLabel(b))}のユーザー提供立ち絵">`;return `<svg class="sprite" viewBox="0 0 280 260" aria-label="カイザーの代替紋章" role="img"><defs><radialGradient id="eg"><stop stop-color="#803b6255"/><stop offset="1" stop-color="#120d1a00"/></radialGradient><linearGradient id="eb" x2="0" y2="1"><stop stop-color="#7c586d"/><stop offset="1" stop-color="#201728"/></linearGradient></defs><ellipse cx="140" cy="130" rx="125" ry="120" fill="url(#eg)"/><g stroke="#88674d" fill="none" opacity=".5"><circle cx="140" cy="120" r="83"/><circle cx="140" cy="120" r="100" stroke-dasharray="1 9"/></g><path d="m119 83-49-66 20 85-53-34 41 61-56 32 73 7-25 62 58-35 13 39 18-39 58 35-25-62 73-7-56-32 41-61-53 34 20-85-49 66Z" fill="#251e30" stroke="#8c6877"/><path d="m93 91 47-29 47 29 8 58-55 47-55-47Z" fill="url(#eb)" stroke="#b68f6d"/><path d="m93 102 47 20 47-20-15 37-32-9-32 9Z" fill="#15121c"/><path d="m107 114 27 10-24 3Zm66 0-27 10 24 3Z" fill="#ee8798"/><path d="m140 85-9 55 9 38 9-38Z" fill="#302433" stroke="#ac8079"/><path d="m110 150 23 4-7 19m44-23-23 4 7 19" stroke="#cca67a" fill="none"/><path d="m108 63 7-25 25 17 25-17 7 25-32-11Z" fill="#ac8359"/></svg>`;}
const COMMAND_ART={slash:'assets/combat-ui-audit9/action-zangeki.webp',feather:'assets/combat-ui-audit9/action-kokuyoku-hadan.webp',pierce:'assets/combat-ui-audit9/action-kokuyoku-hadan.webp',volley:'assets/combat-ui-audit9/action-kokuyoku-hadan.webp',power:'assets/combat-ui-audit9/action-hakai-no-kennou.webp',guard:'assets/combat-ui-audit9/action-bougyo.webp',ultimate:'assets/combat-ui-audit9/action-chou-datengeki-wide.webp'};
function combatIcon(id){
 if(COMMAND_ART[id])return `<img class="command-art" src="${COMMAND_ART[id]}" alt="" width="64" height="64">`;
 const symbols={slash:'swords',feather:'star',pierce:'target',volley:'swords',power:'gem',ultimate:'star',guard:'shield',wait:'shield'};
