d':''} aria-label="${esc(title)}" ${clean?'':`title="${esc(reason||desc)}"`}><span class="glyph ${art?'has-art':''} ${b.character==='irena'?'combat-glyph combat-glyph-'+id:''}">${art?`<img class="skill-art" src="${art}" alt="" width="58" height="58">`:clean?uiIcon(({slash:'swords',guard:'shield',divine:'star',fallen:'crown',godspeed:'power',omnipotent:'crown',dominion:'star',annihilate:'gem',transcend:'shield',grasp:'target',genesis:'star',wait:'shield'})[id]||'gem',26):b.character==='irena'?combatIcon(id):glyph}</span><span class="combat-action-copy"><strong>${title}${!clean&&b.cd[id]>0?'　CT '+b.cd[id]:''}</strong>${clean?'':`<small>${reason||desc}</small>`}</span>${b.character==='irena'?'<span class="combat-chevron" aria-hidden="true">›</span>':''}</button>`;}).join('')}</div>`}</div><aside class="battle-aside stack"><section class="card ${b.character==='irena'?'combat-status-card':''}"><h3>${b.character==='irena'?'権能・自分の状態':'戦況と権能'}</h3>${b.character==='irena'?'<details class="battle-details"><summary>能力値を確認</summary>':''}${statsHTML(p)}<div class="small">敵：攻 ${n(e.atk)} / 防 ${n(e.def)} / 速 ${n(e.spd)}</div>${b.character==='irena'?'</details>':''}${!b.result&&b.enemy.phase===3&&['ex','final'].includes(b.mode)?`<div class="notice" style="margin:14px 0 0">終末判定まで ${Math.max(0,9-b.phaseTurns)}ターン<br>通常行動の停止では防げません。</div>`:''}<div class="statuslist">${b.powers.map(id=>`<span class="pill">${name(id)}${['judge','judgewing','kingjudge','fallenjudge','abyssjudge'].includes(id)?' '+(b.stacks[id]||0)+'/2':''}</span>`).join('')}${b.buffs.map(x=>`<span class="pill gold">${FINAL_SKILLS[x.id]?.name||{divineMight:'神威',godlow:'堕天の神',grasp:'理外掌握',trialFocus:'蓄勢',guardBreakFocus:'蓄勢',campaignFocus:'蓄勢'}[x.id]||x.id} ${x.remaining>900?'∞':x.remaining+'T'}</span>`).join('')}${Object.entries(b.statuses).map(([k,v])=>`<span class="pill">${{stun:'行動不能',seal:'封印',invulnerable:'無敵',pressure:'重圧',slow:'速度低下',fragile:'防御半減'}[k]||k} ${v}T</span>`).join('')}${b.ignoreDefense?`<span class="pill">崩壊 ${b.ignoreDefense}T</span>`:''}${b.noBuff?`<span class="pill">断絶 ${b.noBuff}T</span>`:''}${b.noPressure?`<span class="pill">重圧無効 ${b.noPressure}T</span>`:''}</div></section><section class="card ${b.character==='irena'?'combat-record':''}">${b.character==='irena'?`<p class="last-event" aria-live="polite">${esc(b.log.at(-1)||'戦闘を開始しました')}</p><details class="battle-log"><summary>戦闘記録を開く</summary>`:'<div class="row between" style="margin:0 0 12px"><h3>戦闘記録</h3><span class="tag">COMBAT LOG</span></div>'}<div class="log" aria-live="polite">${[...b.log].reverse().map(x=>`<p>${esc(x)}</p>`).join('')}</div>${b.character==='irena'?'</details>':''}</section>${!b.result?`<div class="compact-combat-tools">${button('能力・状態','combatInfo','','ghost')}${button('戦闘記録','combatLog','','ghost')}${button('撤退','askRetreat','','ghost')}</div>`:''}${!b.result?button('撤退する','askRetreat','','ghost combat-retreat'):''}</aside></div>`;
