 const earned=!b.test&&won?`<div class="reward-grid" aria-label="今回の獲得報酬"><div><small>育成ポイント</small><strong data-reward="p">＋${n(r.p||0)}<em>P</em></strong>${r.bonusP?`<span data-reward="bonusP">初回報酬 ＋${n(r.bonusP)}P を含む</span>`:''}</div><div><small>各権能の欠片</small><strong data-reward="fragments">＋${n(r.fragments||0)}</strong></div><div><small>共鳴片</small><strong data-reward="resShards">＋${n(r.resShards||0)}</strong></div>${r.levels?`<div class="reward-growth"><small>基礎レベル</small><strong data-reward="levels">＋${n(r.levels)} Lv.</strong></div>`:''}${r.sp?`<div class="reward-growth"><small>ステータスポイント</small><strong data-reward="sp">＋${n(r.sp)}P</strong></div>`:''}</div>`:'';
 const discoveries=!b.test?`${r.unlocks?.length?`<div class="result-discoveries"><small>新たに取り戻した力</small>${r.unlocks.map(id=>`<strong data-unlock="${id}">✧ ${unlockNames[id]||esc(id)}</strong>`).join('')}</div>`:''}${r.achievements?.length?`<div class="result-achievements"><small>実績達成 · ${r.achievements.length}件</small>${r.achievements.map(id=>`<span data-achievement="${id}">${esc(ACHIEVEMENTS.find(x=>x.id===id)?.name||id)}</span>`).join('')}${button('実績の報酬を受け取る →','nav','archive','ghost')}</div>`:''}`:'';
 const nextMilestone=won&&b.mode==='normal'&&!b.test?main20Milestones(a).find(([floor])=>!a.cleared.includes(floor)):null;
 return `<section class="result ${victoryArt?'result-illustrated':''}">${victoryArt?`<img class="result-art" src="${SCENES.victory}" alt="通常戦闘の勝利イラスト">`:''}<div class="result-content"><div class="tag">${b.test?'TEST RESULT':'BATTLE RESULT'}</div><h2>${won?'VICTORY':'DEFEAT'}</h2><p class="small">${b.test?'試験戦闘のため本編報酬・実績には反映しません。':won?'失われた力を、またひとつ取り戻した。':'育成を整え、技と装備を組み替えて再挑戦できます。'}${b.mode==='god'&&!won?'<br>今回の仮獲得素材と連戦進行を破棄しました。':''}</p>${earned}${discoveries}${nextMilestone?`<p class="result-next">次の節目：カイザー Lv.${nextMilestone[0]} 撃破で ${nextMilestone[1]}</p>`:''}${r.unlocks?.includes('mystery')?button('？？？？？ — 境界を越える','warp','','primary full'):''}<div class="row" style="justify-content:center">${button('聖域に戻る','finish','','ghost')}${button(won&&b.mode==='normal'&&b.floor<main20Limit(a)?'次の階層へ':b.mode==='god'&&a.gauntlet?'次の神へ':'再挑戦','retry','','primary')}</div></div></section>`;
}
function archive(a){return `${heading('戦いの記憶','全36実績で、天星覇権 Lv.5を取り戻す。','ARCHIVE / ACHIEVEMENTS')}<div class="notice">達成 ${a.achieved.length}/36 / 受取 ${a.claimed.length}件。各実績60Pは手動で1回受取。条件の原本は未回収のため、提供された復元一覧を採用しています。</div><div class="grid triple">${[['A','火力','与ダメージ1.05 / 1.09 / 1.12倍'],['B','技巧','特殊1.08 / 1.12 / 1.15倍、必殺最大1.12倍'],['C','均衡','HP1.05 / HP防1.07 / 全能力1.12倍＋被ダメ0.92倍']].map(([cat,title,text])=>{const rank=badgeRank(a,cat),count=ACHIEVEMENTS.filter(x=>x.cat===cat&&a.achieved.includes(x.id)).length;return `<section class="card"><div class="row between"><span class="badge">${{A:'⚔',B:'✧',C:'⬡'}[cat]}</span><span class="tag">${count} / 12</span></div><h3>${title}の徽章 ${['—','I','II','III'][rank]}</h3><p class="small">3 / 5 / 8個で自動進化。${text}</p><div class="row">${button(a.badge===cat?'装備解除':'装備する','badge',cat,'ghost',!rank)}</div></section>`;}).join('')}</div>${['A','B','C'].map(cat=>`<div class="section-head"><h2>${{A:'A — 火力',B:'B — 技巧',C:'C — 均衡'}[cat]}</h2><span class="tag">12 RECORDS</span></div><div class="grid">${ACHIEVEMENTS.filter(x=>x.cat===cat).map(x=>`<section class="card achievement ${a.achieved.includes(x.id)?'':'locked'}"><div class="emblem">${a.achieved.includes(x.id)?'✧':'◇'}</div><div><h3>${x.name}</h3><p>${a.route20===1&&/^A(6|7|8|9|10|11)$/.test(x.id)?x.detail.replace(/Lv\.(10|30|50|70|90|100)/g,(_,v)=>'第'+(Number(v)/5)+'階層'):x.detail}</p></div>${button(a.claimed.includes(x.id)?'受取済':a.achieved.includes(x.id)?'60P 受取':'未達成','claim',x.id,'',!a.achieved.includes(x.id)||a.claimed.includes(x.id))}</section>`).join('')}</div>`).join('')}`;}
function awakeningView(a){return `${heading('失われた神格','新たな力ではない。かつての自分を、取り戻す。','DIVINE / REAWAKENING')}<div class="grid"><section class="card"><div class="tag">STAGE ${a.awakening} / 5</div><h2>${AWAKENINGS[a.awakening]}</h2><img class="awakening-art" src="${MEDIA.keyArt}" alt="ユーザー提供の共通キービジュアル（覚醒段階別ではありません）"><div class="levelsteps">${Array.from({length:5},(_,i)=>`<i class="${i<a.awakening?'on':''}"></i>`).join('')}</div><p class="small">各段階で通常基礎能力＋18%（補完）。共通キービジュアルを表示しています。5段階の専用絵とMP4は未提供です。</p></section><div class="stack"><section class="card"><h3>神格を取り戻す</h3><p class="small">共通神素材 ${a.godMaterials} / 神域の勲章 ${a.medals}<br>固有素材：${GODS.map((x,i)=>x+' '+a.godUnique[i]).join(' / ')}</p><p>${a.awakening<5?`次：${AWAKENINGS[a.awakening+1]}<br><span class="small">共通素材 ${(a.awakening+1)*5} ＋ ${GODS[a.awakening]}の固有素材1</span>`:'神格は完全に再生された。'}</p><div class="row">${button('手動で覚醒する','awaken','','primary',a.awakening>=5||a.godMaterials<(a.awakening+1)*5||a.godUnique[a.awakening]<1)}</div></section><section class="card"><h3>神域連戦</h3><p class="small">EX撃破後に解放。固定5連戦・各戦全回復。素材は全突破まで仮獲得。敗北・撤退で今回の進行と素材を失います。</p>${a.gauntlet?`<p>第${a.gauntlet.index+1}戦 / 仮素材 ${a.gauntlet.materials}</p>`:''}<div class="row">${button(a.gauntlet?'連戦を続ける':'神域へ挑戦','fight','god','ghost',!a.flags.ex)}</div></section><section class="card"><h3>第5段階の演出基盤</h3><p class="small">専用MP4の再生に対応。現在は10秒のCSS代替演出を使用します。元の覚醒ムービーではありません。</p>${button('代替演出をプレビュー','movie','','ghost')}</section></div></div>`;}
function lab(a){return `${lab20Entry(button)}${heading('境界の実験場','本編の保存データから独立した、戦闘検証空間。','EXPERIMENT / SANDBOX')}<div class="notice">ここで始めた戦闘はすべて試験扱いです。報酬、実績、通常の解放フラグを更新しません。</div><section class="card stack"><h2>戦闘パラメータ</h2><div class="selectline"><label>モード<select id="labmode"><option value="normal">通常いれーな</option><option value="ex">EXカイザー</option><option value="three-phase">EXカイザー・三相決戦【試作】</option><option value="guard-break">熾竜・崩鎧試練【試作】</option><option value="stella">ステラ</option><option value="final">最終決戦いれーな</option></select></label><label>基礎攻撃倍率 <input id="labatk" type="number" value="1" min="0.1" max="20" step=".1"></label><label>基礎HP倍率 <input id="labhp" type="number" value="1" min="0.1" max="20" step=".1"></label></div><p class="small">全育成状態の試験キャラクターを使用。倍率はこの戦闘だけに適用します。三相決戦は黒翼＋堕天王の固定ビルドで開始。第二相から敵が硬化・重圧・回復を発動。破壊の権能・必殺で黒晶殻を解除、防御で重圧を解除、HP12%を回復して蓄勢を獲得。蓄勢は斬撃・破壊の権能を一回強化します。崩鎧試練は固定育成・刻印なしで開始。破壊の権能／必殺の命中で竜の鎧を解除、防御でHP12%回復と次の斬撃／権能の攻撃力3倍を獲得。鎧は実際の被弾3回で再形成されます。羽弾だけでは鎧を崩せません。数値は実験用です。</p>${button('独立試験を開始','labstart','','primary')}</section><div class="section-head"><h2>計算仕様</h2></div><section class="card"><p class="small">基本ダメージ = max(1, 攻撃×技倍率 − 防御×(1−無視率)) × 最終補正 ＋ 現在HP追加。最低保証は最後に適用。低HP倍率は排他的。深淵は基礎値から毎ターン6%の線形減少、下限5%。<br>堕天によるHP倍率は内部の生命割合を維持するため、倍率切替だけでは回復しません。羽弾と断罪の乗算・追加は別枠です。</p></section>`;}
function dev(a){return `${heading('観測者の書架','全機能を検証するための、独立した試験用セーブ。','DEVELOPER / CONTROL')}<div class="notice">「全機能開放」は本編のコピーから試験データを作成します。テスト戦の勝利は実績・初回報酬を付与しません。本編へ戻ると元の進行をそのまま再開できます。天星覇権はここでも36実績条件を維持します。</div><section class="card"><h2>全機能開放</h2><p class="small">全階層、ステラ、EX、最終決戦、共鳴10種、刻印、育成・素材を開放。試験用セーブは独立キーに保存。</p><div class="row">${button(sandbox?'試験データを再作成':'全機能開放','enabledev','','primary')}${sandbox?button('本編へ戻る','exitdev','','ghost'):button('保存済み試験データを開く','resumedev','','ghost')}</div>${sandbox?`<div class="dev-buttons">${[['normal','通常第20階層'],['ex','EXカイザー'],['stella','ステラ最終決戦'],['final','専用いれーな'],['god','神域連戦']].map(([id,title])=>button(title,'fight',id)).join('')}</div>`:''}</section><div class="section-head"><h2>セーブ管理</h2></div><section class="card"><div class="row">${button('JSONバックアップ','export','','ghost')}${button('JSONを読み込む','import','','ghost')}${button('タイトルへ','title','','ghost')}${button('本編を初期化','askReset','','danger')}</div><p class="footnote">保存キー：irena-reborn-v3 / 旧v1・v2キーも検索。未知の旧スキーマは推測して変換せず、エラーを表示します。</p></section>`;}
function tone(kind='hit'){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),g=audio.createGain();osc.connect(g);g.connect(audio.destination);osc.type=kind==='ultimate'?'sawtooth':'sine';osc.frequency.setValueAtTime(kind==='ultimate'?330:620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(80,audio.currentTime+.18);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);osc.start();osc.stop(audio.currentTime+.25);}catch{sound=false;}}
function cinema(type,title,sub,done,duration=2400,art=null){
 if(combatAnimating)return;
 const el=$('#cinema');let completed=false;
 const finish=()=>{if(completed)return;completed=true;clearTimeout(cinemaTimer);el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');try{done?.();}finally{combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();
 el.className='active '+(type==='cut'?'cut':'');el.setAttribute('aria-hidden','false');
 el.innerHTML=`${type==='cut'?`<img src="${art||MEDIA.keyArt}" alt="${esc(title)}の演出画像">`:'<div class="tunnel"></div><div class="tunnel"></div><div class="tunnel"></div>'}<div class="cinema-copy"><h2>${title}</h2><p>${sub}</p></div>${type==='summon'?'<button id="skipCinema" type="button">スキップ</button>':''}`;
 if(type==='summon'){$('#skipCinema').onclick=finish;$('#skipCinema').focus({preventScroll:true});}
 cinemaTimer=setTimeout(finish,matchMedia('(prefers-reduced-motion: reduce)').matches?50:duration);
}
// The alignment pause delays the actual turn (including enemy response) by 200 ms.
// Natural completion commits exactly once. These animations never change combat calculations.
function syncCombatBusy(){
 const busy=combatAnimating||(typeof combatRecovering!=='undefined'&&combatRecovering);
 if(document.documentElement?.dataset)document.documentElement.dataset.combatBusy=String(busy);
 const app=$('#app');if(app)app.inert=busy;
 const controls=$('.battle-controls');controls?.setAttribute?.('aria-busy',String(busy));
}
function alignmentShift(id){
 const reason=available(battle,id);if(reason)throw Error(reason);if(combatAnimating)return;
 const fallen=id==='fallen',el=$('#cinema'),title=fallen?'堕天':'神化';let committed=false,finished=false;
 const commit=()=>{if(committed)return;committed=true;el.classList.add('revealed');doCombat(id);};
 const finish=()=>{if(finished)return;finished=true;clearTimeout(alignmentRevealTimer);clearTimeout(cinemaTimer);try{commit();}finally{el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();el.className='active alignment '+(fallen?'alignment-fallen':'alignment-divine');el.setAttribute('aria-hidden','false');
 el.innerHTML=`<div class="alignment-tint"></div><img class="alignment-crest" src="${fallen?SCENES.fallenCrest:SCENES.divineCrest}" alt="${title}の紋章"><img class="alignment-portrait" src="${fallen?PORTRAITS.fallen:PORTRAITS.divine}" alt="${title}の立ち絵"><div class="alignment-title">${title}</div>`;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 alignmentRevealTimer=setTimeout(commit,reduced?0:200);
 cinemaTimer=setTimeout(finish,reduced?100:850);
}
const STRIKE_ACTIONS=new Set(['slash','feather','pierce','volley','power','ultimate','meteor','annihilate','genesis','ending']);
function showBladeStrike(id){
 if(!STRIKE_ACTIONS.has(id))return;
 const stage=$('.battle-stage');if(!stage)return;
 const strike=document.createElement('div');strike.className='blade-strike';strike.setAttribute('aria-hidden','true');
 strike.innerHTML='<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path class="blade-halo" d="M 6 84 Q 48 45 94 18"/><path class="blade-core" d="M 6 84 Q 48 45 94 18"/><path class="blade-second" d="M 21 92 Q 66 57 88 12"/></svg>';
 stage.append(strike);setTimeout(()=>strike.remove(),650);
}
// Present only combat results already calculated by gameCore. Visual effects never mutate battle state.
function showCombatFeedback(b){
 const arena=$('.battle-stage');if(!arena)return;
 const hits=b.events.filter(x=>x.type==='hit'),foe=arena.querySelector('.fighter-enemy'),player=arena.querySelector('.fighter-player');
 const numbers=(fighter,value,kind)=>{if(!fighter)return;const pop=document.createElement('span');pop.className='combat-number '+kind;pop.setAttribute('aria-hidden','true');pop.textContent=value;fighter.append(pop);setTimeout(()=>pop.remove(),920);};
 const recoil=(fighter,kind)=>{if(!fighter)return;fighter.classList.add(kind);setTimeout(()=>fighter.classList.remove(kind),520);};
 if(b.lastDamage>0){numbers(foe,n(b.lastDamage),'damage-dealt');recoil(foe,'impact-foe');}
 else if(hits.length&&hits.every(x=>x.damage===0))numbers(foe,'MISS','damage-missed');
 if(b.enemyDamage>0){numbers(player,'−'+n(b.enemyDamage),'damage-taken');recoil(player,'impact-player');}
}
function beginFight(mode,options={}){const a=current();if(battle&&!battle.result)throw Error('進行中の戦闘があります。先に戦闘画面から撤退してください。');if(mode==='god'&&!a.gauntlet)startGauntlet(a);const floor=options.floor??(mode==='normal'?a.floor:100);battle=startMainBattle(a,{mode,floor,difficulty:mode==='normal'?difficulty:'NORMAL',test:!!sandbox,...options});selectedFloor=floor;page='battle';persist();render();window.scrollTo(0,0);}
function doCombat(id,route='A'){
 const b=battle;if(!b||b.result)return;
 combatRecovering=true;clearTimeout(combatReleaseTimer);syncCombatBusy();
 try{
  const previousPhase=b.enemy.phase;if(b.lab20)actLab20(b,id,{route});else if(b.main20)actMainBattle(b,id,{route});else if(b.campaign)actCampaign(b,id,{route});else if(b.trial?.kind==='guard-break')actGuardBreakTrial(b,id,{route});else if(b.trial)actThreePhase(b,id,{route});else act(b,id,{route});b.lastAction=id;
  if(b.result){b.reward=b.lab20?settleLab20(lab20Run,b):b.main20?settleMainBattle(current(),b):b.campaign?settleCampaign(campaign,b):settle(current(),b);if(!b.test&&b.result==='win'&&id==='ultimate'&&b.used.marks.includes('starfall')){current().records.starfinish=true;achievements(current());}if(!b.lab20&&(!b.campaign||b.main20)&&(!b.test||sandbox))persist();}
  if(!b.result&&!b.test&&b.character==='irena')persist();
  tone(['ultimate','meteor','annihilate','genesis','ending'].includes(id)?'ultimate':'hit');render();
  if(b.events.some(x=>x.type==='hit')||b.lastDamage>0)showBladeStrike(id);showCombatFeedback(b);
  if(b.trial?.kind==='three-phase'&&!b.result&&b.enemy.phase>previousPhase){const active=b;setTimeout(()=>{if(battle!==active||battle.result)return;cinema('cut',b.enemy.phase===3?'第三相・終極':'第二相・変転','EX KAISER · THREE PHASE',null,850,ENEMIES.ex);$('#cinema').classList.add('phase-transition');},0);}
 }finally{
  syncCombatBusy();
  combatReleaseTimer=setTimeout(()=>{combatRecovering=false;syncCombatBusy();},matchMedia('(prefers-reduced-motion: reduce)').matches?60:280);
 }
}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function importFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('ファイルが大きすぎます（上限2MB）');const data=validateMain20(JSON.parse(await file.text()));modal('セーブを復元',`<p>Lv.${data.level} / 到達Lv.${data.floor} / ${data.achieved.length}実績のデータです。${sandbox?'試験用':'本編'}セーブを上書きします。読み込み前のバックアップを書き出せます。</p>`,button('現在のJSONを書き出し','export','','ghost')+button('このデータに置き換える','confirmImport','','primary'));$('#modal').querySelector('[data-action="confirmImport"]').onclick=event=>{event.stopPropagation();if(battle&&!battle.result){toast('進行中の戦闘を撤退してから読み込んでください');return;}if(sandbox)sandbox=data;else s=data;saveBlocked=false;battle=sandbox?null:restoreMarkBattle(s.markBattle,validateSave);page='home';const stored=persist();close();render();toast(stored?'JSONから復元しました':'JSONを読み込みましたが、端末への保存に失敗しました。JSONバックアップを保持してください。');};}catch(e){toast('読み込み失敗：'+e.message);}};input.click();}
async function handle(action,id){if(combatAnimating||combatRecovering)return;const a=current();switch(action){
 case 'begin':if(saveBlocked){confirmDialog('読み込めない既存セーブがあります','新しい旅を始めると保存済みデータを上書きします。既存のデータを残す場合は閉じて、正しいJSONを読み込んでください。','newAfterError','');break;}a.started=true;persist();render();break;
 case 'newAfterError':saveBlocked=false;s=freshMain20();s.started=true;persist();close();render();break;
 case 'nav':if(id==='upgrade')tab='overview';page=id;render();window.scrollTo(0,0);break;
 case 'openupgrade':page='upgrade';tab=id;render();window.scrollTo(0,0);break;
 case 'upgradeBack':tab='overview';render();window.scrollTo(0,0);break;
 case 'sortPowers':powerSort=powerSort==='default'?'owned':'default';render();break;
 case 'powerDetails':{const power=POWERS.find(x=>x.id===id);if(!power)throw Error('権能が見つかりません');modal(power.name,powerDetails(a,power));break;}
 case 'tab':tab=id;render();break;
 case 'combatInfo':if(battle)modal('能力・現在の状態',`<h3>自分</h3>${statsHTML(playerStats(battle))}<h3>敵</h3>${statsHTML(enemyStats(battle))}<p>${esc($('.fighter-enemy .actual-enemy-state')?.textContent||'')}</p><div class="statuslist">${$('.battle-aside .statuslist')?.innerHTML||''}</div>${battle.enemy.phase===3&&['ex','final'].includes(battle.mode)?`<p>終末判定まで ${Math.max(0,9-battle.phaseTurns)}ターン</p>`:''}`);break;
 case 'combatLog':if(battle)modal('戦闘記録',`<div class="log">${[...battle.log].reverse().map(x=>`<p>${esc(x)}</p>`).join('')}</div>`);break;
 case 'focusCommands':$('.battle-controls')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
 case 'focusStage':$('.battle-stage')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
 case 'sound':sound=!sound;if(sound)tone();render();break;
 case 'about':modal('いれーな REBORN',`<p>本作は提供仕様書を基準とする新規復元版です。元のHTML・JSON・画像はこの環境では取得できていません。</p><p>まず通常カイザーを倒して育成。第10階層で共鳴とレイド、第20階層突破後の「？？？？？」からステラを解放します。ステラ解放でEXに挑戦でき、ステラ最終決戦の勝利で専用いれーなが解放されます。</p><p>確定した権能倍率・専用技・実績36件は維持。敵の基礎値・経済・権能Lv成長・共鳴の未回収値・神域ボスは補完設計です。ホームのキービジュアルと堕天の技アイコンはユーザー提供画像です。未提供の立ち絵は代替SVGを使用しています。</p><p>自動保存に加え、定期的にJSONを書き出してください。戦闘中の一時状態は再起動でリセットされます。Safari実機は未確認です。音は任意の合成SEのみ。</p>`);break;
 case 'close':close();break;
 case 'equipPower':equip(a,id,'power');persist();render();break;
 case 'equipMark':equip(a,id,'mark');persist();render();break;
 case 'buyPower':buyPower(a,id);persist();render();toast(name(id)+'を取り戻した');break;
