 case 'buyMark':buyMark(a,id);persist();render();break;
 case 'askFuse':confirmDialog('権能共鳴',`${name(id)}を合成します。元権能2つを消費・装備解除します。余剰欠片は共鳴片に変換。このレシピは再使用できません。`,'fuse',id);break;
 case 'fuse':fuse(a,id);persist();close();render();toast(name(id)+'が共鳴した');break;
 case 'train':train(a,id);persist();render();break;
